import{_ as n,C as a,c as r,o as l,aa as s,G as t}from"./chunks/framework.Cn7WEiMX.js";const b=JSON.parse('{"title":"插件特色","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/features.md","filePath":"wiki/Dynmap/features.md"}'),p={name:"wiki/Dynmap/features.md"};function c(_,e,m,d,u,f){const o=a("NolebaseGitContributors"),i=a("NolebaseGitChangelog");return l(),r("div",null,[e[0]||(e[0]=s('<h1 id="插件特色" tabindex="-1">插件特色 <a class="header-anchor" href="#插件特色" aria-label="Permalink to &quot;插件特色&quot;">​</a></h1> <p>可以在浏览器中查看服务器的实时地图，且界面类似谷歌地图。通过 Dynmap 内置的网页服务器，开箱即可投入使用，同时它也可以与在 Apache 等平台上运行的其他网站一并使用。Dynmap 可使用不同的渲染器绘制地图，部分注重西性能，而其他的则注重细节。</p> <p>组件允许你添加/移除功能，使得 Dynmap 更符合你的需求。通过组件，Dynmap 可以支持聊天气泡、网页与游戏内实时同步聊天，以及可配置的标记、区域及线条等。</p> <h2 id="插件特色-1" tabindex="-1">插件特色 <a class="header-anchor" href="#插件特色-1" aria-label="Permalink to &quot;插件特色&quot;">​</a></h2> <ul><li>全局及分世界均高度可配置。</li> <li>实时更新：与世界实时同步更新，浏览器打开后持续显示地图变动。</li> <li>玩家会在地图上以其头像显示。</li> <li>聊天消息在地图上可见（气泡或聊天框）。</li> <li>浏览地图的玩家可与服务器内玩家聊天。</li> <li>地图会显示当前 Minecraft 时间与天气。</li> <li>WorldGuard、Residence、Towny 与 Factions 插件的区域会显示在地图上（通过各自的 Dynmap-* 拓展插件）。</li></ul> ',10)),t(o),t(i)])}const D=n(p,[["render",c]]);export{b as __pageData,D as default};
